// Build-time only: runs the pinned original private cinematic cameras (client/demon-cinematic.ts, the Raging Demon victim
// screen with shared/raging-demon.ts's clock, and client/siren/cutscene.ts, the Last Laugh grab cutscene) on synthetic
// snapshots, and records what Tests/CinematicCameraChecks.cs compares with the C# port (Core/NativeCinematicRules.cs).
// The expected values are never generated by the C# port.
// Usage: node tools/export_cinematic_cameras.mjs <source checkout at 05950ea with node_modules> -> Tests/cinematic-camera-parity.json
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),source=path.resolve(process.argv[2]);
const pinned={'src/client/demon-cinematic.ts':'cd7ead4a7fc029a9496dd3be09b791082330ed00','src/client/siren/cutscene.ts':'09b461a0e7a8f55e81ba343a36427a680a5a442b',
 'src/shared/raging-demon.ts':'1d2debfa5b30cc2a4bbd86f23f70e9ef2d9cf7d8','src/shared/siren-contract.ts':'ad494dfd203d8f12cdfc69b2c73004807af28ccc',
 'src/client/pve/boss-look.ts':'6e46d406440b73bf6df059f374d3275cece18e62','src/client/raging-demon.ts':'808134f9f397adb14d9aaab9ca8c9fe1226cfa0f'};
for(const [file,blob] of Object.entries(pinned)){const bytes=fs.readFileSync(path.join(source,file));if(createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex')!==blob)throw Error('Source blob mismatch: '+file);}
const {register}=await import(pathToFileURL(path.join(source,'node_modules/tsx/dist/esm/api/index.mjs')).href);register();
const load=f=>import(pathToFileURL(path.join(source,'src',f)).href);
const T=await import(pathToFileURL(path.join(source,'node_modules/three/build/three.module.js')).href);
const {DemonCinematic}=await load('client/demon-cinematic.ts'),{SirenCutscene,CUTSCENE_TAIL}=await load('client/siren/cutscene.ts');
const {RAGING_DEMON}=await load('shared/raging-demon.ts'),{SIREN_TIMING}=await load('shared/siren-contract.ts'),{bossVisualScale}=await load('client/pve/boss-look.ts');
const r6=x=>Math.round(x*1e6)/1e6,arr=v=>v.toArray().map(r6);
const cosmetics={hat:'none',bodyColor:'#e5e7eb',intro:'neon-drop',overrideWeaponIntro:true,killEffect:'dev-raging-demon'};
const pilot=(id,pos,yaw,hp=100)=>({id,name:id,spec:'pistol',class:'ranged',hp,maxHp:100,color:'#70e1d0',developer:true,yaw,pitch:0,pos,vel:{x:0,y:0,z:0},chips:{},cosmetics,blockTime:0,blockCd:0,connected:true});

// The victim screen (death at 0, so each age is exact): every age across the window (and just outside it), three aspects, the baked in-world fixture (no
// attacker, yaw 0), an attacker off to the side, one too close (the death yaw decides) and a far one.
const deaths=[
 {name:'fixture',pos:{x:0,y:.865,z:0},yaw:0},
 {name:'attacker',pos:{x:3,y:1.1,z:-2},yaw:.7,attacker:{x:5.5,y:.9,z:-3.2}},
 {name:'close',pos:{x:-4,y:.865,z:6},yaw:-2.1,attacker:{x:-3.2,y:.865,z:6.9}},
 {name:'far',pos:{x:10,y:2,z:1},yaw:2.8,attacker:{x:-6,y:.865,z:12}}];
const ages=[.5,.549,.55,.6,.719,.72,.79,.8,.9,.97,1.02,1.1,1.19,1.3,1.5,1.7,1.95,2.0,2.3,2.6,2.75,2.89,2.9,3.06,3.2,3.6,4.0,4.24,4.25,4.4];
const aspects=[16/9,1,.5];
const demon=[];
for(const d of deaths)for(const aspect of aspects){
 const cinema=new DemonCinematic();
 for(const age of ages){
  const at=0,p=pilot('victim',d.pos,d.yaw,0);p.death={id:'death-'+d.name,at,effect:'dev-raging-demon',seed:5,pos:d.pos,yaw:d.yaw,velocity:{x:0,y:0,z:0},direction:{x:0,y:0,z:1},force:0,
   attacker:d.attacker?{pos:d.attacker,yaw:0,color:'#ff274c',cosmetics:{...cosmetics},spec:'ansatsuken'}:undefined};
  const state={generation:1,time:at+age,players:[p],options:{gameMode:'ffa'},phase:'fight'};
  const on=cinema.update(state,'victim',aspect,1),c=cinema.camera,root=cinema.scene.getObjectByName('raging-demon');
  demon.push(on?{death:d.name,aspect:r6(aspect),age,on,eye:arr(c.position),dir:arr(c.getWorldDirection(new T.Vector3())),fov:r6(c.fov),backdrop:[r6(cinema.backdrop.r),r6(cinema.backdrop.g),r6(cinema.backdrop.b)],visible:root.visible}:{death:d.name,aspect:r6(aspect),age,on});
 }
 cinema.clear();
}

// The grab cutscene at 30 fps (offset so no frame lands on a shot or story boundary): both roles, a turning Siren (with and without a rig, so the eased facing follows the rig or the
// yaw), a grown PvE Siren, the victim's head tracked from a rig until the victim dies, one take with a wall that pulls the
// camera in, an interrupted hold, a hold whose grab ends at the crush (the scene plays on), and a phase change.
const AT=10,CRUSH=AT+SIREN_TIMING.laugh.crush,RELEASE=AT+SIREN_TIMING.laugh.release;
const takes=[
 {name:'victim',role:'victim',rig:true,victimRig:true},
 {name:'siren',role:'siren',rig:false,victimRig:false},
 {name:'siren-rig',role:'siren',rig:true,victimRig:true,wall:true},
 {name:'grown',role:'victim',rig:false,victimRig:false,boost:1.5},
 {name:'interrupted',role:'victim',rig:true,victimRig:true,gone:AT+1.7},
 {name:'released',role:'siren',rig:false,victimRig:true,gone:CRUSH+.02},
 {name:'phase',role:'victim',rig:false,victimRig:false,phase:AT+2.5}];
const siren=[],wallX=-.2;let walls=0;
for(const take of takes){
 const cut=new SirenCutscene(),camera=new T.PerspectiveCamera(60,16/9,.08,400);const frames=[];let time=AT-.19;
 while(time<CRUSH+CUTSCENE_TAIL+.25){
  const yaw=.4+.9*Math.sin((time-AT)*.8),rigYaw=yaw+.15,owner=pilot('siren',{x:1+.3*Math.sin(time),y:1.2,z:2-.2*Math.cos(time*.7)},yaw);
  if(take.boost)owner.siren={boost:{scale:take.boost,at:AT-.4}};
  const dead=time>=CRUSH,victim=pilot('victim',{x:owner.pos.x+.9,y:2.05,z:owner.pos.z+.3},0,dead?0:60);
  const grab=take.gone!==undefined&&time>=take.gone?[]:[{owner:'siren',victim:'victim',at:AT,crushAt:CRUSH,releaseAt:RELEASE}];
  const phase=take.phase!==undefined&&time>=take.phase?'countdown':'fight';
  const state={time,phase,players:[owner,victim],siren:{grabs:time>=AT?grab:[]}};
  const me=take.role==='victim'?'victim':'siren';
  const sirenHead={x:owner.pos.x+.05*Math.sin(time*3),y:owner.pos.y+.8+.04*Math.cos(time*2),z:owner.pos.z+.1};
  const victimHead={x:victim.pos.x+.02*Math.sin(time*5),y:victim.pos.y+.6,z:victim.pos.z-.05};
  const rig=(head,y)=>({group:{visible:true,rotation:{y},updateMatrixWorld(){}},head:{getWorldPosition:v=>v.set(head.x,head.y,head.z)}});
  const rigs=new Map();if(take.rig)rigs.set('siren',rig(sirenHead,rigYaw));if(take.victimRig)rigs.set('victim',rig(victimHead,0));
  // A wall plane at x = wallX (the props raycast): the distance along the ray to it, if within range.
  const occlusion=take.wall?(o,d,dist)=>{if(d.x>=-1e-9)return null;const hit=(wallX-o.x)/d.x;if(hit>=0&&hit<=dist){walls++;return hit;}return null;}:undefined;
  const active=cut.check(state,me);let frame={time,active,phase,grab:grab.length>0&&time>=AT,owner:[owner.pos.x,owner.pos.y,owner.pos.z],yaw,rigYaw,
   scale:r6(owner.siren?bossVisualScale(owner.siren.boost,time):1),sirenHead:[sirenHead.x,sirenHead.y,sirenHead.z],victimHead:[victimHead.x,victimHead.y,victimHead.z],victimHp:victim.hp};
  if(active){
   cut.update(state,camera,rigs,occlusion);
   const up=new T.Vector3(0,1,0).applyQuaternion(camera.quaternion),bars=cut.bars,top=cut.top;let k=0;
   if(bars.visible){const bar=top.scale.y,h=bar/.12;k=1-(top.position.y-h/2+bar/2)/bar;}
   frame={...frame,role:cut.role,position:arr(camera.position),dir:arr(camera.getWorldDirection(new T.Vector3())),up:arr(up),fov:r6(camera.fov),bars:bars.visible,k:r6(k)};
  }
  frames.push(frame);time+=1/30;
 }
 siren.push({name:take.name,role:take.role,rig:take.rig,victimRig:take.victimRig,wall:!!take.wall,wallX,frames});
}
fs.writeFileSync(path.join(root,'Tests/cinematic-camera-parity.json'),JSON.stringify({source:'05950ea',raging:RAGING_DEMON,laugh:SIREN_TIMING.laugh,tail:CUTSCENE_TAIL,grab:{at:AT,crush:CRUSH,release:RELEASE},deaths,demon,siren}));
console.log("walls",walls,"demon",demon.length,'siren',siren.reduce((n,t)=>n+t.frames.length,0));
